import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { SPRINGS } from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

// ---- EXACT frame timings from the script (25fps) ----
// Frames = ss*25 + ff
const ITEMS = [
  { label: "Location identifier", frame: 0, icon: "pin" },     // 00:00:00:00
  { label: "Delivery zone", frame: 30, icon: "zone" },         // 00:00:01:05 -> 1*25+5
  { label: "Your own rating", frame: 57, icon: "star" },       // 00:00:02:07 -> 2*25+7
  { label: "Competitor rating", frame: 86, icon: "versus" },   // 00:00:03:11 -> 3*25+11
  { label: "Price index", frame: 114, icon: "price" },         // 00:00:04:14 -> 4*25+14
  { label: "Run date", frame: 135, icon: "date" },             // 00:00:05:10 -> 5*25+10
];

const SCENE_DUR = 200;
export const durationInFrames = SCENE_DUR;

// ---------- Background (painted once at root) ----------
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ---------- Icons ----------
const Icon: React.FC<{ kind: string; size: number; color: string }> = ({
  kind,
  size,
  color,
}) => {
  const common = {
    stroke: color,
    strokeWidth: 2.5,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
    fill: "none",
  };
  switch (kind) {
    case "pin":
      return (
        <svg width={size} height={size} viewBox="0 0 24 24">
          <path d="M12 21s7-6.5 7-12a7 7 0 0 0-14 0c0 5.5 7 12 7 12Z" {...common} />
          <circle cx="12" cy="9" r="2.6" {...common} />
        </svg>
      );
    case "zone":
      return (
        <svg width={size} height={size} viewBox="0 0 24 24">
          <circle cx="12" cy="12" r="8.5" {...common} strokeDasharray="3 3" />
          <circle cx="12" cy="12" r="2.4" fill={color} stroke="none" />
        </svg>
      );
    case "star":
      return (
        <svg width={size} height={size} viewBox="0 0 24 24">
          <path
            d="M12 3.5l2.6 5.3 5.9.85-4.25 4.15 1 5.85L12 17l-5.25 2.7 1-5.85L3.5 9.65l5.9-.85z"
            {...common}
          />
        </svg>
      );
    case "versus":
      return (
        <svg width={size} height={size} viewBox="0 0 24 24">
          <path d="M8 4l-4 8 4 8" {...common} />
          <path d="M16 4l4 8-4 8" {...common} />
          <path d="M12 3v18" {...common} strokeDasharray="2 3" />
        </svg>
      );
    case "price":
      return (
        <svg width={size} height={size} viewBox="0 0 24 24">
          <path d="M12 4v16" {...common} />
          <path
            d="M15.5 8c0-1.7-1.6-2.6-3.5-2.6S8.5 6.4 8.5 8s1.6 2.4 3.5 2.9 3.5 1.3 3.5 3-1.6 2.7-3.5 2.7-3.5-1-3.5-2.7"
            {...common}
          />
        </svg>
      );
    case "date":
      return (
        <svg width={size} height={size} viewBox="0 0 24 24">
          <rect x="4" y="5" width="16" height="15" rx="2.5" {...common} />
          <path d="M4 9.5h16M8 3.5v3.5M16 3.5v3.5" {...common} />
          <circle cx="12" cy="14.5" r="1.6" fill={color} stroke="none" />
        </svg>
      );
    default:
      return null;
  }
};

// ---------- Row ----------
const Row: React.FC<{
  item: (typeof ITEMS)[number];
  index: number;
  rowH: number;
  iconSize: number;
  iconTile: number;
  radius: number;
  padH: number;
  gap: number;
  labelSize: number;
  ordSize: number;
}> = ({
  item,
  index,
  rowH,
  iconSize,
  iconTile,
  radius,
  padH,
  gap,
  labelSize,
  ordSize,
}) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Pop-up EXACTLY at the item's frame — no offset.
  const p = spring({
    frame,
    fps: vfps,
    delay: item.frame,
    config: SPRINGS.ELASTIC,
  });

  const opacity = interpolate(p, [0, 0.4], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const tx = interpolate(p, [0, 1], [-60, 0]);
  const sc = interpolate(p, [0, 1], [0.9, 1]);

  const iconP = spring({
    frame,
    fps: vfps,
    delay: item.frame + 3,
    config: SPRINGS.SNAPPY,
  });
  const iconScale = interpolate(iconP, [0, 1], [0.4, 1]);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap,
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: radius,
        padding: `0 ${padH}px`,
        height: rowH,
        boxSizing: "border-box",
        opacity,
        // No idle/ambient motion — rows are perfectly still after popping in.
        transform: `translateX(${tx}px) scale(${sc})`,
        boxShadow: "0 12px 32px rgba(0,0,0,0.4)",
      }}
    >
      <div
        style={{
          width: iconTile,
          height: iconTile,
          flexShrink: 0,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: COLORS.card,
          border: `1.5px solid ${COLORS.orange}`,
          borderRadius: radius * 0.8,
          transform: `scale(${iconScale})`,
        }}
      >
        <Icon kind={item.icon} size={iconSize} color={COLORS.orange} />
      </div>

      <div
        style={{
          fontFamily: "'GT Walsheim', Inter, sans-serif",
          fontWeight: 600,
          fontSize: labelSize,
          color: COLORS.text,
          letterSpacing: "-0.015em",
          lineHeight: 1.05,
        }}
      >
        {item.label}
      </div>

      <div
        style={{
          marginLeft: "auto",
          fontFamily: "monospace",
          fontSize: ordSize,
          color: COLORS.textSubtle,
          letterSpacing: "0.1em",
        }}
      >
        {String(index + 1).padStart(2, "0")}
      </div>
    </div>
  );
};

// ---------- Scene ----------
const ListScene: React.FC = () => {
  const { width, height } = useVideoConfig();

  // Explicit fit math for a 2160x2160 square.
  const margin = height * 0.1;
  const availableH = height - margin * 2;
  const rowGap = height * 0.026;
  const rows = ITEMS.length;
  const rowH = (availableH - rowGap * (rows - 1)) / rows;

  const colW = width * 0.74;

  const iconTile = rowH * 0.6;
  const iconSize = iconTile * 0.58;
  const radius = rowH * 0.16;
  const padH = rowH * 0.28;
  const gap = rowH * 0.3;
  const labelSize = rowH * 0.34;
  const ordSize = rowH * 0.18;

  return (
    <AbsoluteFill>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: "translate(-50%, -50%)",
          width: colW,
          display: "flex",
          flexDirection: "column",
          gap: rowGap,
        }}
      >
        {ITEMS.map((item, i) => (
          <Row
            key={i}
            item={item}
            index={i}
            rowH={rowH}
            iconSize={iconSize}
            iconTile={iconTile}
            radius={radius}
            padH={padH}
            gap={gap}
            labelSize={labelSize}
            ordSize={ordSize}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

// ---------- Main composition ----------
// Static frame — no cameraDrift, no ambient/idle motion anywhere.
const MainComposition: React.FC = () => {
  return (
    <AbsoluteFill>
      {/* transparent foreground; Background stripped on alpha export */}
      <ListScene />
    </AbsoluteFill>
  );
};

export default MainComposition;
